  "Was für eine Art Musik magst du?": "Che genere di musica ti piace?",
  "Draußen ist dichter Nebel.": "Fuori c'è una nebbia fitta.",
  "Das ist aber ein seriöses Angebot.": "Questa sì che è un'offerta seria.",
  "Das Lokal ist gerade sehr angesagt.": "Quel locale adesso va molto di moda.",
  "Mein Handy ist kaputt.": "Il mio cellulare è rotto.",
  "Wir waren am Sonntag in der Messe.": "Domenica siamo stati alla fiera.",
  "Ich muss noch zur Bank, dann zum Frisör.": "Devo ancora andare in banca e poi dal parrucchiere.",
  "Das Gymnasium hat einen guten Ruf.": "Il liceo ha una buona reputazione.",
  "Sie ist gerade in der Fabrik.": "Adesso è in fabbrica.",
  "Er muss immer seinen Senf dazugeben.": "Deve sempre dire la sua.",
  "Mit ihm ist nicht gut Kirschen essen.": "Con lui non è aria.",
  "Er hat nicht alle Tassen im Schrank.": "Gli manca qualche venerdì.",
  "Er hat Tomaten auf den Augen.": "Ha le fette di salame sugli occhi.",
  "Er redet immer um den heißen Brei herum.": "Gira sempre intorno al discorso.",
  "Sie hat ihm einen Korb gegeben.": "Gli ha dato il due di picche.",
  "Da hast du echt Schwein gehabt!": "Lì hai avuto una bella botta di fortuna!",
  "Ich drücke dir morgen die Daumen.": "Domani ti incrocio le dita.",
  "Ich hab heute einen Kater.": "Oggi ho i postumi della sbornia.",
  "Ich bin heute nicht ganz auf dem Damm.": "Oggi non sono in gran forma.",
  "Wir müssen in den sauren Apfel beißen.": "Dobbiamo ingoiare il rospo.",
  "Der Zug ist leider abgefahren.": "Purtroppo quel treno è passato.",
  "Das kannst du dir abschminken.": "Puoi togliertelo dalla testa.",
  "Das ist doch Jacke wie Hose.": "Se non è zuppa è pan bagnato.",
  "Das ist doch Schnee von gestern.": "È acqua passata.",
  "Das passt wie die Faust aufs Auge.": "Sta come i cavoli a merenda.",
  "Das kommt mir spanisch vor.": "Qui gatta ci cova.",
  "Das ist nur ein Katzensprung von hier.": "È a due passi da qui.",
  "So schlagen wir zwei Fliegen mit einer Klappe.": "Così prendiamo due piccioni con una fava.",
  "Ich glaub, mein Schwein pfeift.": "Non credo ai miei occhi.",
  "Das geht mir auf den Keks.": "Mi sta sulle scatole.",
  "Bring mich nicht auf die Palme.": "Non farmi saltare i nervi.",
  "Ich hab die Nase voll.": "Ne ho fin sopra i capelli.",
  "Wir sehen den Wald vor lauter Bäumen nicht.": "Gli alberi non ci fanno vedere il bosco.",
  "Ich versteh nur noch Bahnhof heute.": "Oggi non ci capisco più niente.",
  "Aller Anfang ist schwer.": "Ogni inizio è difficile.",
  "Morgenstund hat Gold im Mund.": "Il mattino ha l'oro in bocca.",
  "Halt die Ohren steif!": "Fatti coraggio!",
  "Ich hab echt Schwein gehabt — genau mein Thema kam dran.": "Ho avuto una fortuna sfacciata: è uscito proprio il mio argomento.",
  "Siehst du! Und du wolltest absagen.": "Lo vedi! E tu volevi disdire.",
  "Tja, aller Anfang ist schwer.": "Eh, ogni inizio è difficile.",
  // ── block 10 — a day of ordinary talk, from the barber to the party ──
  "Meier hat schon wieder seinen Senf dazugegeben.": "Meier ha detto di nuovo la sua.",
  "Der redet auch immer um den heißen Brei herum.": "E per giunta gira sempre intorno al discorso.",
  "Langsam geht er mir auf den Keks.": "Piano piano mi sta sulle scatole.",
  "Ruhig. Nächste Woche hat er Urlaub.": "Calma. La settimana prossima è in ferie.",
  "Tja, da kann man nichts machen.": "Eh, non c'è niente da fare.",
  "Na ja, es war okay.": "Beh, è andata così così.",
  "Hach, war das schön.": "Ah, che bello è stato.",
  "Schon wieder Ersatzverkehr — na super.": "Di nuovo servizio sostitutivo, che bello.",
  "Menno, immer ich!": "Uffa, sempre io!",
  "Igitt, das ist ja noch vom letzten Jahr!": "Bleah, ma questo è dell'anno scorso!",
  "Pfui! Spuck das aus!": "Che schifo! Sputalo!",
  "Autsch, das tat weh.": "Ahi, ha fatto male.",
  "Huch, du hast mich erschreckt!": "Ops, mi hai spaventato!",
  "Hoppla, das sollte nicht passieren.": "Ehi, non doveva succedere.",
  "Ups, falsche Nummer.": "Ops, numero sbagliato.",
  "Oje, das klingt gar nicht gut.": "Ahi ahi, non suona per niente bene.",
  "Juhu, es hat geklappt!": "Evviva, ha funzionato!",
  "Boah, ist das groß!": "Caspita, com'è grande!",
  "Tada! Fertig ist das Regal.": "Ta-dà! Lo scaffale è pronto.",
  "Oha, das ist mal eine Ansage.": "Però, questa sì che è una dichiarazione.",
  "Uff, endlich geschafft.": "Uff, finalmente fatto.",
  "Puh, das war knapp.": "Uff, c'è mancato poco.",
  "Mist, ich hab die Milch vergessen.": "Accidenti, ho dimenticato il latte.",
  "Quatsch, das hast du dir ausgedacht!": "Ma va', te lo sei inventato!",
  "Pfff, das glaubst du doch selbst nicht.": "Bah, non ci credi neanche tu.",
  "Hä? Das ergibt doch keinen Sinn.": "Eh? Ma non ha nessun senso.",
  "Hmm, da bin ich mir nicht sicher.": "Mmm, su questo non sono sicuro.",
  "Ähm, wie heißt das noch mal?": "Ehm, come si chiamava?",
  "Ach so, jetzt versteh ich!": "Ah, ecco, adesso ho capito!",
  "Pst, die Kleine schläft.": "Sst, la piccola dorme.",
  "So, jetzt aber los.": "Su, adesso andiamo.",
  "Na dann bis morgen!": "E allora a domani!",
  "Igitt was ist das denn hinten im Kühlschrank?": "Bleah! E quello che cos'è, in fondo al frigorifero?",
  "Oje. Ich glaub das war mal Käse.": "Ahi ahi. Credo che una volta fosse formaggio.",
  "Pfui. Das kommt sofort weg.": "Che schifo. Quello va via subito.",
  "Puh, gut, dass du es gefunden hast und nicht ich.": "Uff, meno male che l'hai trovato tu e non io.",
  "Boah, schon wieder zwanzig Minuten Verspätung.": "Caspita, di nuovo venti minuti di ritardo.",
  "Hmm, sollen wir den Bus nehmen?": "Mmm, prendiamo l'autobus?",
  "Ach so, der fährt ja auch. Na dann, los!": "Ah, giusto, va anche quello. E allora andiamo!",
  "Ich wohn in einer WG.": "Vivo in un appartamento condiviso.",
  "Wir suchen noch jemanden für unser WG-Zimmer.": "Cerchiamo ancora qualcuno per la stanza libera.",
  "Er macht eine Ausbildung als Azubi bei einer Bank.": "Fa l'apprendista in una banca.",
  "Die Wohnung liegt im EG, das Büro im dritten OG.": "L'appartamento è al pianterreno e l'ufficio al terzo piano.",
  "Die Firma ist eine GmbH.": "L'azienda è una società a responsabilità limitata.",
  "Sie arbeitet beim TÜV.": "Lavora alla motorizzazione tedesca.",
  "Mein Sohn ist in der Kita, meine Tochter schon an der Uni.": "Mio figlio va all'asilo e mia figlia è già all'università.",
  "Nach dem Abi will sie erst mal reisen.": "Dopo la maturità vuole prima viaggiare.",
  "Der Parkplatz ist nur für PKW.": "Il parcheggio è solo per autovetture.",
  "Wir treffen uns am Hbf, Gleis eins.": "Ci troviamo alla stazione centrale, binario uno.",
  "Die U-Bahn kommt alle fünf Minuten.": "La metropolitana passa ogni cinque minuti.",
  "Wir treffen uns an der S-Bahn.": "Ci troviamo al treno suburbano.",
  "Nimm was Warmes mit, z. B. eine Jacke.": "Porta qualcosa di caldo, per es. una giacca.",
  "Der Preis gilt inkl. MwSt.": "Il prezzo è IVA inclusa.",
  "Bring Teller, Besteck, Gläser usw. mit.": "Porta piatti, posate, bicchieri ecc.",
  "Steht das schon im Kalender, inkl. Uhrzeit?": "È già in calendario, con l'ora?",
  "Zahlen Sie mit EC-Karte oder bar?": "Paga con carta di debito o in contanti?",
  "Sie bekommt BAföG fürs Studium.": "Riceve la borsa di studio per l'università.",
  "Keine Ahnung was die Abkürzung heißt — frag Google.": "Non ho idea di che voglia dire la sigla: chiedi a Google.",
  "Wir wohnen im dritten OG, ohne Aufzug.": "Abitiamo al terzo piano, senza ascensore.",
  "Puh. Und die WG ist wie groß?": "Uff. E quanto è grande l'appartamento condiviso?",
