  "Klingt gut. Ich komm mit der S-Bahn.": "Suona bene. Io vengo con il treno suburbano.",
  "Treffen wir uns am Hbf?": "Ci troviamo alla stazione centrale?",
  "Lieber an der U-Bahn, Gleis zwei.": "Meglio alla metropolitana, binario due.",
  "Typisch. Dann hol ich uns schon mal Kaffee.": "Tipico. Allora intanto vado a prendere il caffè.",
  "Ich hätte gern einen Termin zum Schneiden.": "Vorrei un appuntamento per il taglio.",
  "Haben Sie heute noch etwas frei?": "Le resta qualcosa di libero per oggi?",
