  "Nur die Spitzen, bitte.": "Solo le punte, per favore.",
  "Ungefähr zwei Zentimeter kürzer.": "Circa due centimetri più corto.",
  "Bitte nicht zu kurz — beim letzten Mal war es zu viel.": "Non troppo corto, per favore: l'ultima volta è stato troppo.",
  "Der Pony fällt mir ständig in die Augen.": "La frangia mi cade in continuazione sugli occhi.",
  "Können Sie den Pony etwas kürzer schneiden?": "Mi può accorciare un po' la frangia?",
  "Vorne etwas länger lassen, hinten kürzer.": "Davanti un po' più lungo, dietro più corto.",
