  "Ich lass mir die Haare wachsen.": "Mi sto facendo crescere i capelli.",
  "Der Scheitel sitzt heute irgendwie schief.": "Oggi la riga mi è venuta storta.",
  "Machen Sie den Nacken bitte mit dem Rasierer sauber.": "Mi pulisca la nuca con il rasoio, per favore.",
  "Ich möchte den Ansatz nachfärben lassen.": "Vorrei farmi ritoccare la ricrescita.",
  "Eher dunkler oder eher heller?": "Più scuro o più chiaro?",
  "Nur eine Tönung, bitte, nichts Dauerhaftes.": "Solo un colore semipermanente, per favore, niente di definitivo.",
