  "Kannst du beim Schleppen helfen? Ich bestelle Pizza für alle.": "Mi dai una mano a caricare? Offro la pizza a tutti.",
  "Vorsicht, die Kiste ist schwerer, als sie aussieht.": "Attento, la cassa pesa più di quanto sembri.",
  "Das Sofa passt nicht durchs Treppenhaus.": "Il divano non passa per le scale.",
  "Der Schrank wird abgebaut und drüben wieder aufgebaut.": "L'armadio si smonta e si rimonta di là.",
  "Lass uns zuerst das Bett aufbauen, der Rest kann warten.": "Montiamo prima il letto, il resto può aspettare.",
  "Wo soll das Regal hin?": "Dove va lo scaffale?",
  "Ich finde den Karton mit den Handtüchern nicht.": "Non trovo lo scatolone degli asciugamani.",
