  "Bei der Übergabe zählen wir die Schlüssel.": "Alla consegna contiamo le chiavi.",
  "Die alten Möbel kommen auf den Sperrmüll.": "I mobili vecchi vanno con i rifiuti ingombranti.",
  "Die Nachbarn haben sich schon vorgestellt.": "I vicini si sono già presentati.",
