  "Gut, dann mach ich schon mal das Fenster zu und packe die Taschen.": "Bene, intanto chiudo la finestra e preparo le borse.",
  "Hast du Kleingeld für den Einkaufswagen?": "Hai spiccioli per il carrello?",
  "Nein, aber wir nehmen einfach den Korb. So viel brauchen wir nicht.": "No, ma prendiamo il cestino e basta. Non ci serve poi tanto.",
  "Komm rein! Die Schuhe kannst du gern anlassen.": "Entra pure! Le scarpe puoi tenerle.",
  "Schön hell hier. Seit wann wohnst du im dritten Stock?": "Che luce qui. Da quando abiti al terzo piano?",
  "Seit zwei Monaten. Die Küche ist klein, aber sie reicht mir.": "Da due mesi. La cucina è piccola, ma a me basta.",
  "Und der Balkon! Da bleib ich im Sommer gleich zum Essen.": "E il balcone! D'estate lì ci resto anche a cena.",
  "Gern. Nur der Aufzug ist leider öfter kaputt als er fährt.": "Quando vuoi. Solo che l'ascensore purtroppo è rotto più spesso di quanto funzioni.",
