  "Mach ich. Muskelkater in den Waden hab ich auch noch.": "Lo faccio. Ho anche i dolori muscolari ai polpacci.",
  "Was steht heute an? Der Rasen?": "Che cosa c'è in programma oggi? Il prato?",
  "Mähen, ja. Und im Beet wächst nur noch Unkraut.": "Tagliarlo, sì. E nell'aiuola cresce ormai solo erbaccia.",
  "Ich übernehme das Beet, und danach hältst du mir die Leiter fest.": "Mi occupo io dell'aiuola, e dopo mi tieni ferma la scala.",
  "Für den Baum? Der muss wirklich geschnitten werden.": "Per l'albero? Va davvero potato.",
  "Genau. Und abends gießen wir die Blumen und sind fertig.": "Esatto. E la sera annaffiamo i fiori e abbiamo finito.",
  "Danke. Wie viele Quadratmeter hat die Wohnung?": "Grazie. Quanti metri quadrati ha l'appartamento?",
  "Zweiundsechzig, zwei Zimmer, Küche, Bad.": "Sessantadue, due stanze, cucina, bagno.",
