  "Und ab wann wäre sie frei?": "E da quando sarebbe libero?",
  "Entschuldigung, ist dieses Abteil noch frei?": "Mi scusi, questo scompartimento è ancora libero?",
  "Ja, kommen Sie rein. Müssen Sie auch umsteigen?": "Sì, venga pure. Deve cambiare anche lei?",
  "Einmal, aber der Anschlusszug wartet. Wir wollen an die Küste, zelten.": "Una volta sola, ma il treno in coincidenza aspetta. Andiamo sulla costa, in tenda.",
  "Schön! Die Wellen sollen dieses Wochenende ziemlich hoch sein.": "Bello! Le onde questo fine settimana dovrebbero essere piuttosto alte.",
  "Perfekt für die Kinder. Zelt, Lagerfeuer, grillen — mehr brauchen wir nicht.": "Perfetto per i bambini. Tenda, falò, grigliata: non ci serve altro.",
  "Ich hab keinen Ziffernblock.": "Non ho il tastierino numerico.",
  "Dann nutz die Sonderzeichentasten unter dem Eingabefeld.": "Allora usa i tasti dei caratteri speciali sotto il campo di inserimento.",
