  "Uns fehlten wichtige Zahlen weshalb wir warten mussten.": "Ci mancavano dei dati importanti, motivo per cui abbiamo dovuto aspettare.",
  "Sind die Daten inzwischen vollständig?": "I dati nel frattempo sono completi?",
  "Ja, daher können wir den Bericht morgen abschließen.": "Sì, perciò domani possiamo chiudere la relazione.",
  "Zuerst wollte ich mit dem Zug fahren.": "All'inizio volevo andare in treno.",
