  "Es stellte sich heraus dass der Ersatzbus am anderen Ausgang hielt.": "È saltato fuori che l'autobus sostitutivo fermava all'altra uscita.",
  "Habt ihr den verlorenen Schlüssel noch gefunden?": "L'avete poi trovata la chiave persa?",
  "Ja. Ausgerechnet der Hund hatte ihn unter das Sofa geschoben.": "Sì. Guarda caso era stato il cane a spingerla sotto il divano.",
  "Wie habt ihr ihn gefunden?": "E come l'avete trovata?",
  "Zum Glück hat er später wieder damit gespielt.": "Per fortuna dopo ci ha giocato di nuovo.",
