  "Nichts. Rote Lampe am Router.": "Niente. Spia rossa sul router.",
  "Dann ist es eine Störung im Haus, nicht bei uns.": "Allora è un guasto nel palazzo, non da noi.",
  "Ich melde es, du fragst mal bei Nummer sieben.": "Io lo segnalo, tu chiedi al numero sette.",
  "Der Techniker kommt Donnerstag zwischen acht und zwölf.": "Il tecnico viene giovedì fra le otto e le dodici.",
  "Also der halbe Tag weg.": "Quindi mezza giornata persa.",
  "Kannst du Homeoffice machen?": "Puoi lavorare da casa?",
  "Ohne Internet? Ironisch, aber ja — mit Hotspot.": "Senza internet? Ironico, ma sì: con l'hotspot.",
  "Warst du beim Friseur? Das steht dir richtig gut.": "Sei stata dal parrucchiere? Ti sta davvero bene.",
  "Ach, gestern erst. Ich bin noch nicht ganz sicher.": "Ah, solo ieri. Non ne sono ancora del tutto sicura.",
  "Ehrlich: viel frischer. Und die Farbe passt zu dir.": "Sinceramente: molto più fresco. E il colore ti si addice.",
  "Danke, das freut mich wirklich.": "Grazie, mi fa davvero piacere.",
  "Ach, das war doch nichts Besonderes.": "Ma va', non è stato niente di speciale.",
  "Doch, war es. Nimm das Kompliment einfach an.": "Sì che lo è stato. Accetta il complimento e basta.",
  "Na gut. Danke — das tut gut.": "E va bene. Grazie: fa piacere.",
  "Wir haben uns getrennt.": "Ci siamo lasciati.",
  "Oh nein. Das tut mir leid.": "Oh no. Mi dispiace.",
  "Es ist im Guten, wirklich. Wir haben uns auseinandergelebt.": "È finita bene, davvero. Ci siamo allontanati.",
  "Ich bin da wenn du reden willst — egal wann.": "Ci sono io se vuoi parlare, a qualsiasi ora.",
  "Wie machen wir es mit den Kindern?": "Come facciamo con i bambini?",
  "Wechselmodell? Eine Woche bei dir, eine bei mir.": "Affido alternato? Una settimana da te, una da me.",
  "Und feste Übergaben damit sie wissen, woran sie sind.": "E scambi a orari fissi, così sanno a che punto stanno.",
  "Einverstanden. Und wir reden gut übereinander.": "D'accordo. E parliamo bene l'uno dell'altro.",
  "Wie viel Eigenkapital bringen Sie mit?": "Quanto capitale proprio porta?",
  "Achtzigtausend, plus die Nebenkosten separat.": "Ottantamila, più le spese accessorie a parte.",
  "Sehr gut. Bei zehn Jahren Bindung wären wir bei knapp vier Prozent.": "Molto bene. Con un vincolo di dieci anni saremmo a poco meno del quattro per cento.",
  "Und mit drei Prozent Tilgung? Rechnen Sie das einmal durch.": "E con il tre per cento di ammortamento? Faccia il conto per intero.",
  "Schön ist es. Aber die Heizung ist von neunzehnneunzig.": "Bella è bella. Ma l'impianto di riscaldamento è del millenovecentonovanta.",
  "Und das Dach? Stand nichts im Exposé.": "E il tetto? Nell'annuncio non c'era scritto niente.",
  "Deshalb lassen wir ein Gutachten machen.": "Ed è per questo che facciamo fare una perizia.",
  "Einverstanden. Vorher unterschreiben wir gar nichts.": "D'accordo. Prima non firmiamo proprio niente.",
  "Ich hätte gern ein warmes Grau.": "Vorrei un grigio caldo.",
  "Auf der Karte sieht das fast weiß aus.": "Sul cartoncino sembra quasi bianco.",
  "An der Wand wirkt es viel dunkler, sagt der Verkäufer.": "Sul muro fa un effetto molto più scuro, dice il commesso.",
  "Dann kaufen wir eine kleine Dose und probieren es aus.": "Allora compriamo un barattolo piccolo e proviamo.",
  "Fertig! Sieht doch gut aus.": "Finito! Sta bene, no?",
  "Da vorne schimmert das alte Blau noch durch.": "Là davanti si intravede ancora il vecchio blu.",
  "Also doch ein zweiter Anstrich.": "Quindi ci vuole una seconda mano.",
  "Vier Stunden warten, dann machen wir es fertig.": "Aspettare quattro ore e poi lo finiamo.",
  "Entschuldigung, könnten Sie ein Foto von uns machen?": "Mi scusi, ci potrebbe fare una foto?",
  "Klar. Einfach hier drücken?": "Certo. Basta premere qui?",
  "Genau. Und die Kirche gern mit drauf.": "Esatto. E ci metta dentro volentieri anche la chiesa.",
  "Ich mach drei, dann ist sicher eins dabei.": "Ne faccio tre, così una buona di sicuro c'è.",
  "Alle mal zusammenrücken!": "Stringetevi tutti!",
  "Opa, du stehst genau hinter Tante Rita.": "Nonno, sei proprio dietro a zia Rita.",
  "Auf drei — und nicht blinzeln! Eins, zwei ...": "Al tre, e non sbattete le palpebre! Uno, due...",
  "Warte, jetzt fehlst du selbst. Selbstauslöser!": "Aspetta, adesso manchi tu. Autoscatto!",
  "Ich hätte so gern einen Hund.": "Mi piacerebbe tanto avere un cane.",
  "Und wer geht im Winter um sechs raus?": "E chi esce d'inverno alle sei?",
  "Abwechselnd. Und im Urlaub Tierpension.": "A turno. E in vacanza la pensione per animali.",
  "Dann schauen wir uns mal im Tierheim um.": "Allora diamo un'occhiata al canile.",
  "Wie viele Stunden wäre er allein?": "Quante ore resterebbe da solo?",
  "Höchstens vier, wir arbeiten beide im Wechsel.": "Al massimo quattro, lavoriamo tutti e due a turni.",
  "Gut. Wir machen dann noch eine Vorkontrolle bei Ihnen.": "Bene. Faremo poi anche una visita preliminare da voi.",
  "Sehr gern. Fragen Sie ruhig alles.": "Molto volentieri. Chieda pure tutto.",
  "Können Sie mir einen Kostenvoranschlag machen?": "Mi può fare un preventivo?",
